import zipfile, re
p='/root/event_announcement_ready.hwpx'
labels = ['행사명','일시','장소','주최','주관']
found = []
with zipfile.ZipFile(p) as z:
    for name in z.namelist():
        if not name.lower().endswith('.xml'):
            continue
        text = z.read(name).decode('utf-8', errors='replace')
        for lab in labels:
            if lab in text:
                found.append(lab)
# Show unique found labels
uniq=[]
for x in found:
    if x not in uniq:
        uniq.append(x)
print('Found labels:', uniq)
